func fallbackText(value string) string {
	if value == "" {
		return "Non renseigné"
	}
	return value
}

func firstNonEmpty(values ...string) string {
	for _, value := range values {
		if value != "" {
			return value
		}
	}
	return ""
}

func individualVoteGroups(votes []ScrutinIndividualVote) []IndividualVoteGroup {
	groups := make([]IndividualVoteGroup, 0)
	indexes := make(map[string]int)
	for _, vote := range votes {
		key := individualVoteGroupKey(vote)
		index, ok := indexes[key]
		if !ok {
			index = len(groups)
			indexes[key] = index
			groups = append(groups, IndividualVoteGroup{
				GroupeUID: vote.GroupeUID,
				Groupe:    individualVoteGroupLabel(vote),
			})
		}
		groups[index].Votes = append(groups[index].Votes, vote)
	}
	return groups
}

func individualVoteGroupKey(vote ScrutinIndividualVote) string {
	return firstNonEmpty(vote.GroupeUID, vote.Groupe, "sans-groupe")
}

func individualVoteGroupLabel(vote ScrutinIndividualVote) string {
	return firstNonEmpty(vote.Groupe, vote.GroupeUID, "Sans groupe")
}

func individualVotePositionLabel(position string) string {
	switch strings.ToLower(strings.TrimSpace(position)) {
	case "pour":
		return "Pour"
	case "contre":
		return "Contre"
	case "abstention":
		return "Abstention"
	case "non_votant":
		return "Non votant"
	case "non_votant_volontaire":
		return "Non votant volontaire"
	default:
		return fallbackText(position)
	}
}

func individualVotePositionClass(position string) string {
	base := "vote-position"
	switch strings.ToLower(strings.TrimSpace(position)) {
	case "pour":
		return base + " vote-position--pour"
	case "contre":
		return base + " vote-position--contre"
	case "abstention":
		return base + " vote-position--abstention"
	case "non_votant", "non_votant_volontaire":
		return base + " vote-position--non-votant"
	default:
		return base
	}
}

func delegationLabel(parDelegation bool) string {
	if parDelegation {
		return "Oui"
	}
	return "Non"
}

func numberOrEmpty(value int) string {
	if value == 0 {
		return ""
	}
	return strconv.Itoa(value)
}

func officialScrutinURL(scrutin ScrutinDetailData) string {
	if scrutin.Legislature <= 0 || scrutin.Numero <= 0 {
		return ""
	}
	return "https://www.assemblee-nationale.fr/dyn/" + strconv.Itoa(scrutin.Legislature) + "/scrutins/" + strconv.Itoa(scrutin.Numero)
}

func hasLinkedReference(scrutin ScrutinDetailData) bool {
	return scrutin.LinkedTextNum != "" || scrutin.LinkedTextURL != "" || scrutin.LinkedTextPDFURL != "" || scrutin.LinkedDossierRef != "" || scrutin.LinkedAmendementNum != "" || scrutin.LinkedAmendementURL != ""
}

func linkedTextSummary(scrutin ScrutinDetailData) string {
	textNum := scrutin.LinkedTextNum
	textKind := linkedTextKindLabel(scrutin.LinkedTextKind)
	if textNum == "" {
		return textKind
	}
	if textKind == "" {
		return "n° " + textNum
	}
	return "n° " + textNum + " · " + textKind
}

func linkedAmendementSummary(scrutin ScrutinDetailData) string {
	if scrutin.LinkedAmendementNum == "" {
		return ""
	}
	parts := []string{"n° " + scrutin.LinkedAmendementNum}
	if scrutin.LinkedAmendementTextNum != "" {
		parts = append(parts, "texte "+scrutin.LinkedAmendementTextNum)
	}
	if scrutin.LinkedAmendementOrgane != "" {
		parts = append(parts, scrutin.LinkedAmendementOrgane)
	}
	return strings.Join(parts, " · ")
}

func linkedDossierSummary(scrutin ScrutinDetailData) string {
	if scrutin.LinkedDossierLibelle != "" {
		return scrutin.LinkedDossierLibelle
	}
	return scrutin.LinkedDossierRef
}

func officialLinkedTextURL(scrutin ScrutinDetailData) string {
	if scrutin.LinkedTextURL != "" {
		return scrutin.LinkedTextURL
	}
	if scrutin.Legislature <= 0 || scrutin.LinkedTextNum == "" || scrutin.LinkedTextKind == "" {
		return ""
	}
	return "https://www.assemblee-nationale.fr/dyn/" + strconv.Itoa(scrutin.Legislature) + "/textes/l" + strconv.Itoa(scrutin.Legislature) + "b" + leftPad(scrutin.LinkedTextNum, 4) + "_" + scrutin.LinkedTextKind
}

func officialLinkedTextPDFURL(scrutin ScrutinDetailData) string {
	return scrutin.LinkedTextPDFURL
}

func leftPad(value string, length int) string {
	for len(value) < length {
		value = "0" + value
	}
	return value
}

func officialDossierURL(scrutin ScrutinDetailData) string {
	if scrutin.Legislature <= 0 || scrutin.LinkedDossierRef == "" {
		return ""
	}
	return "https://www.assemblee-nationale.fr/dyn/" + strconv.Itoa(scrutin.Legislature) + "/dossiers/" + scrutin.LinkedDossierRef
}

func officialAmendementURL(scrutin ScrutinDetailData) string {
	return scrutin.LinkedAmendementURL
}

func linkedTextKindLabel(kind string) string {
	switch kind {
	case "projet-loi":
		return "Projet de loi"
	case "proposition-loi":
		return "Proposition de loi"
	case "texte-adopte-commission":
		return "Texte adopté en commission"
	case "texte-adopte-seance":
		return "Texte adopté en séance"
	default:
		return kind
	}
}

func linkedReferenceSourceLabel(source string) string {
	switch source {
	case "titre":
		return "Titre"
	case "objet":
		return "Objet"
	case "titre+objet":
		return "Titre et objet"
	default:
		return source
	}
}

func votersTotal(scrutin ScrutinDetailData) int {
	if scrutin.NombreVotants > 0 {
		return scrutin.NombreVotants
	}
	return scrutin.Pour + scrutin.Contre + scrutin.Abstentions
}

func nonVotingDeputies(scrutin ScrutinDetailData) int {
	nonVoting := totalDeputies - votersTotal(scrutin)
	if nonVoting < 0 {
		return 0
	}
	return nonVoting
}

func groupVoteSegments(groupVote ScrutinGroupVote) []VoteSegment {
	return []VoteSegment{
		{Label: "Pour", Count: groupVote.Pour, Class: "vote-segment--pour"},
		{Label: "Abstentions", Count: groupVote.Abstentions, Class: "vote-segment--abstention"},
		{Label: "Contre", Count: groupVote.Contre, Class: "vote-segment--contre"},
	}
}

func groupVoteTotal(groupVote ScrutinGroupVote) int {
	return groupVote.Pour + groupVote.Contre + groupVote.Abstentions
}

func groupVoteChartBarClass(groupVote ScrutinGroupVote) string {
	if groupVoteTotal(groupVote) == 0 {
		return "group-vote-chart__bar group-vote-chart__bar--empty"
	}
	return "group-vote-chart__bar"
}

func groupVoteStackedLabel(groupVote ScrutinGroupVote) string {
	if groupVoteTotal(groupVote) == 0 {
		return groupVote.Groupe + " : aucun vote exprimé"
	}
	return voteBreakdownLabel(groupVote.Groupe, groupVoteSegments(groupVote), groupVoteTotal(groupVote))
}

func groupVoteChartCells(groupVote ScrutinGroupVote) []VoteCell {
	cells := voteBreakdownCells(groupVoteSegments(groupVote), groupVoteTotal(groupVote))
	for index, cell := range cells {
		cells[index].Title = groupVoteSegmentTitle(groupVote, cell.Label)
	}
	return cells
}

func groupVoteSegmentTitle(groupVote ScrutinGroupVote, label string) string {
	count := 0
	switch label {
	case "Pour":
		count = groupVote.Pour
	case "Abstentions":
		count = groupVote.Abstentions
	case "Contre":
		count = groupVote.Contre
	}
	return groupVote.Groupe + " - " + label + " : " + strconv.Itoa(count) + " voix (" + votePercent(count, groupVoteTotal(groupVote)) + ")"
}

func groupPourDeviation(scrutin ScrutinDetailData, groupVote ScrutinGroupVote) float64 {
	return voteRatio(groupVote.Pour, groupVoteTotal(groupVote)) - voteRatio(scrutin.Pour, votersTotal(scrutin))
}

func groupPourDeviationAvailable(scrutin ScrutinDetailData, groupVote ScrutinGroupVote) bool {
	return votersTotal(scrutin) > 0 && groupVoteTotal(groupVote) > 0 && !groupVoteOnlyAbstentions(groupVote)
}

func groupPourDeviationLabel(scrutin ScrutinDetailData, groupVote ScrutinGroupVote) string {
	return groupVote.Groupe + " : " + votePercent(groupVote.Pour, groupVoteTotal(groupVote)) + " de Pour, " + signedPercentPoints(groupPourDeviation(scrutin, groupVote)) + " par rapport à l'hémicycle"
}

func groupPourDeviationUnavailableLabel(scrutin ScrutinDetailData, groupVote ScrutinGroupVote) string {
	if groupVoteTotal(groupVote) == 0 {
		return groupVote.Groupe + " : aucun vote exprimé, écart non calculé"
	}
	if groupVoteOnlyAbstentions(groupVote) {
		return groupVote.Groupe + " : abstentions uniquement, écart au vote Pour non représenté"
	}
	if votersTotal(scrutin) == 0 {
		return groupVote.Groupe + " : référence hémicycle indisponible, écart non calculé"
	}
	return groupVote.Groupe + " : écart non calculé"
}

func groupPourDeviationUnavailableValue(groupVote ScrutinGroupVote) string {
	if groupVoteOnlyAbstentions(groupVote) {
		return "Abst. seule"
	}
	return "-"
}

func groupPourDeviationUnavailableValueClass(groupVote ScrutinGroupVote) string {
	if groupVoteOnlyAbstentions(groupVote) {
		return "group-deviation-chart__value group-deviation-chart__value--abstention"
	}
	return "group-deviation-chart__value group-deviation-chart__value--empty"
}

func groupVoteOnlyAbstentions(groupVote ScrutinGroupVote) bool {
	return groupVote.Abstentions > 0 && groupVote.Pour == 0 && groupVote.Contre == 0
}

func groupDeviationValueClass(deviation float64) string {
	if deviation > 0 {
		return "group-deviation-chart__value group-deviation-chart__value--positive"
	}
	if deviation < 0 {
		return "group-deviation-chart__value group-deviation-chart__value--negative"
	}
	return "group-deviation-chart__value"
}

func groupDeviationCellClass(index int, deviation float64) string {
	const centerIndex = groupDeviationCellCount / 2
	const step = 5.0

	position := float64(index-centerIndex) * step
	class := "group-deviation-cell"
	if index == centerIndex {
		return class + " group-deviation-cell--center"
	}
	if deviation > 0 && position > 0 && position <= deviation+step/2 {
		return class + " group-deviation-cell--positive"
	}
	if deviation < 0 && position < 0 && position >= deviation-step/2 {
		return class + " group-deviation-cell--negative"
	}
	return class
}

func groupDeviationEmptyCellClass(index int) string {
	const centerIndex = groupDeviationCellCount / 2
	if index == centerIndex {
		return "group-deviation-cell group-deviation-cell--center"
	}
	return "group-deviation-cell group-deviation-cell--empty"
}

func signedPercentPoints(value float64) string {
	if value > 0 {
		return "+" + strconv.FormatFloat(value, 'f', 1, 64) + " pts"
	}
	return strconv.FormatFloat(value, 'f', 1, 64) + " pts"
}

func voteRatio(count int, total int) float64 {
	if count <= 0 || total <= 0 {
		return 0
	}
	return (float64(count) / float64(total)) * 100
}

func sortedGroupVotesForChart(groupVotes []ScrutinGroupVote) []ScrutinGroupVote {
	sorted := append([]ScrutinGroupVote(nil), groupVotes...)
	sort.SliceStable(sorted, func(i int, j int) bool {
		leftRank := groupPoliticalRank(sorted[i].Groupe)
		rightRank := groupPoliticalRank(sorted[j].Groupe)
		if leftRank == rightRank {
			return strings.Compare(sorted[i].Groupe, sorted[j].Groupe) < 0
		}
		return leftRank < rightRank
	})
	return sorted
}

func groupPoliticalRank(group string) int {
	ranks := map[string]int{
		"LFI-NFP": 10,
		"GDR":     20,
		"ECOS":    30,
		"SOC":     40,
		"LIOT":    50,
		"DEM":     60,
		"EPR":     70,
		"HOR":     80,
		"DR":      90,
		"NI":      100,
		"UDR":     110,
		"RN":      120,
	}
	if rank, ok := ranks[strings.ToUpper(strings.TrimSpace(group))]; ok {
		return rank
	}
	return 1000
}

func votePercent(count int, total int) string {
	if count <= 0 || total <= 0 {
		return "0%"
	}
	percent := voteRatio(count, total)
	return strconv.FormatFloat(percent, 'f', 1, 64) + "%"
}

func voteBreakdownLabel(title string, segments []VoteSegment, total int) string {
	label := title + ", total " + strconv.Itoa(total)
	for _, segment := range segments {
		label += ", " + segment.Label + " " + strconv.Itoa(segment.Count) + " (" + votePercent(segment.Count, total) + ")"
	}
	return label
}

func voteBreakdownCells(segments []VoteSegment, total int) []VoteCell {
	const cellCount = 100

	cells := make([]VoteCell, 0, cellCount)
	if total <= 0 {
		return cells
	}

	for index := range cellCount {
		position := (float64(index) + 0.5) * float64(total) / cellCount
		cumulative := 0
		cell := VoteCell{Label: "Non renseigné", Class: "vote-segment--non-votant"}

		for _, segment := range segments {
			if segment.Count <= 0 {
				continue
			}
			cumulative += segment.Count
			if position < float64(cumulative) {
				cell = VoteCell{Label: segment.Label, Class: segment.Class}
				break
			}
		}

		cells = append(cells, cell)
	}

	return cells
}

